mapper.select:
select * from article

    state='已发布' and workflow_status='PUBLISHED'

        and category_id=#{categoryId}


        and state=#{state}


        and create_user=#{userId}


order by create_time desc

select distinct a.id, a.title, a.summary, a.cover_img, a.state, a.category_id, a.source_id, a.original_url, a.original_title, a.source_language, a.original_published_at, a.original_published_date, a.ingested_at, a.published_at, a.content_type, a.reading_mode, a.workflow_status, a.workflow_reason_code, a.tags, a.heat, a.is_carousel, a.views, a.create_time, a.update_time from article a join article_game ag on ag.article_id = a.id join game g on g.id = ag.game_id and g.enabled = 1
a.state = '已发布' and a.workflow_status = 'PUBLISHED'
and g.code = #{gameCode}
and a.content_type = #{contentType}
order by coalesce(a.published_at, a.update_time) desc, a.id desc
